// Chunking por títulos numerados del manual (la jerarquía de # que devuelve LlamaParse varía por página)
function chunkManual(texto) {
  const lineas = String(texto).replace(/\r/g, '').split('\n');
  const reCap = /^#{1,4}\s*\**\s*(\d{1,2})\.\s+(.+?)\**\s*$/;
  const reSub = /^#{1,4}\s*\**\s*(\d{1,2})\.(\d{1,2})\s+(.+?)\**\s*$/;
  const limpiar = (s) => s.replace(/\*\*/g, '').trim();
  const chunks = [];
  let capitulo = 'Datos del documento', actual = { seccion: '0', titulo: 'Datos del documento', lineas: [] };
  const cerrar = () => {
    const cuerpo = actual.lineas.join('\n').replace(/^-{3,}\s*$/gm, '').replace(/\n{3,}/g, '\n\n').trim();
    if (cuerpo) chunks.push({ seccion: actual.seccion, capitulo, titulo: actual.titulo, cuerpo });
  };
  for (const l of lineas) {
    const s = l.match(reSub), c = !s && l.match(reCap);
    if (s) { cerrar(); actual = { seccion: `${s[1]}.${s[2]}`, titulo: limpiar(s[3]), lineas: [] }; }
    else if (c) { cerrar(); capitulo = `${c[1]}. ${limpiar(c[2])}`; actual = { seccion: c[1], titulo: limpiar(c[2]), lineas: [] }; }
    else if (/^#\s/.test(l) && chunks.length === 0 && actual.lineas.length === 0) { /* título del documento */ }
    else actual.lineas.push(l);
  }
  cerrar();
  return chunks.map((ch, i) => {
    const contenido = `Manual de soporte de ProTable v1.0 · ${ch.capitulo} · Sección ${ch.seccion} ${ch.titulo}\n\n${ch.cuerpo.replace(/\*\*/g, '')}`;
    return { chunk_id: `m5-${String(i + 1).padStart(3, '0')}`, seccion: ch.seccion, capitulo: ch.capitulo, titulo: ch.titulo, contenido, tokens_aprox: Math.ceil(contenido.length / 4), version_manual: '1.0' };
  });
}

const texto = $input.first().json.text;
return chunkManual(texto).map((c) => ({ json: c }));
